with filtered as (select id, city, segment, signup_date, is_active, credit_limit, age, lower(name) as name_lower, coalesce(segment, 'N/A') as resolved_segment from customers where signup_date >= to_date('2023-03-27') and segment is not null) select * from (select *, row_number() over (partition by segment order by age desc nulls first, id) as rank_in_group from filtered) x where rank_in_group = 1
